select jsonb_build_object(
'at', now(),
'verify', (select jsonb_object_agg(r, (select count(*) filter (where not matches)||'/'||count(*) from costing.fn_verify_run_fingerprint(r))) from unnest(array[119,121,122,124,125,126,127,128]::bigint[]) r),
'feed_md5', (select md5(string_agg(f::text,'|' order by period_start, sku_id)) from costing.v_price_revision_feed_approved f),
'feed_n', (select count(*) from costing.v_price_revision_feed_approved),
'pub_feed_md5', (select md5(string_agg(f::text,'|' order by f::text)) from public.v_costing_pricing_price_revision_feed_approved f),
'cron', (select md5(string_agg(jobid||':'||jobname||':'||schedule||':'||active||':'||command,'|' order by jobid)) from cron.job),
'cron_6061', (select jsonb_agg(jobid||':'||active order by jobid) from cron.job where jobid in (60,61)),
'periods', (select jsonb_agg(period_start||':'||status||':'||coalesce(locked_at::text,'-')||':'||coalesce(closed_at::text,'-') order by period_start) from costing.cost_periods where period_start >= '2026-08-01'),
'designations', (select md5(string_agg(to_jsonb(d)::text,'|' order by id)) from costing.costing_run_designation d),
'runs', (select md5(string_agg(id||':'||overall_status,'|' order by id)) from costing.costing_refresh_run),
'fp_rows', (select count(*) from costing.costing_run_fingerprint),
'costing_tup', (select jsonb_build_object('ins',sum(n_tup_ins),'upd',sum(n_tup_upd),'del',sum(n_tup_del),'live',sum(n_live_tup)) from pg_stat_user_tables where schemaname='costing'),
'ledger_md5', (select md5(string_agg(to_jsonb(l)::text,'|' order by id)) from costing.cost_head_policy_ledger l),
'capacity_md5', (select md5(string_agg(to_jsonb(p)::text,'|' order by id)) from costing.plant_capacity_profile p),
'class_md5', (select md5(string_agg(to_jsonb(p)::text,'|' order by id)) from costing.route_equipment_load_capacity p),
'switches', (select md5(coalesce((select string_agg(to_jsonb(s)::text,'|') from costing.plant_aware_load_switch s),'')||coalesce((select string_agg(to_jsonb(s)::text,'|') from costing.costing_sales_feed_switch s),'')||coalesce((select string_agg(to_jsonb(s)::text,'|') from costing.batch_true_standard_switch s),'')||coalesce((select string_agg(to_jsonb(s)::text,'|') from costing.route_load_scaling_switch s),'')||coalesce((select string_agg(to_jsonb(s)::text,'|') from costing.cost_head_policy_switch s),''))),
'tally_rows', (select jsonb_object_agg(relname, n_live_tup) from pg_stat_user_tables where schemaname='public' and (relname like 'tally%' or relname='etl_jobs')),
'tally_pol', (select jsonb_agg(tablename||':'||policyname||':'||cmd order by tablename, policyname) from pg_policies where schemaname='public' and (tablename like 'tally%' or tablename='etl_jobs')),
'tally_acl', (select jsonb_object_agg(relname, relacl::text) from pg_class where relnamespace='public'::regnamespace and relkind='r' and (relname like 'tally%' or relname='etl_jobs')),
'view_acl', (select jsonb_object_agg(relname, coalesce(relacl::text,'')||' '||coalesce(array_to_string(reloptions,','),'')) from pg_class where relnamespace='public'::regnamespace and relkind='v' and (relname like 'v_costing%' or relname like 'v_cost_sheet%')),
'view_gated', (select count(*) from pg_class where relnamespace='public'::regnamespace and relkind='v' and (relname like 'v_costing%' or relname like 'v_cost_sheet%') and pg_get_viewdef(oid) ~ '(fn_costing_view_allowed|app_has_permission|require_permission)'),
'fn_cfg', (select jsonb_object_agg(p.oid::regprocedure::text, coalesce(array_to_string(proconfig,','),'')) from pg_proc p where proname in ('fn_sales_allocation_quantity_driver_fingerprint','fn_au3_append_only','fn_fy_start','fn_tally_classify_export_window','fn_tally_batch_consistency','fn_enforce_prm_approval_reference','fn_regional_marketing_evidence_fingerprint','fn_apply_batch_true_standard','fn_w2_require_text')),
'fn_out', jsonb_build_array(costing.fn_fy_start('2026-02-10'), costing.fn_fy_start('2026-10-19'),
   costing.fn_sales_allocation_quantity_driver_fingerprint(1,2,'2026-10-01','m','s','2026-09-01',3,4,'x',5.5,6.25),
   costing.fn_regional_marketing_evidence_fingerprint(1,2,' ke ','2026-10-01','b',1,2,3,4,'s','m',7.5,0.25),
   (select to_jsonb(t) from public.fn_tally_classify_export_window('2026-10-19','2026-04-01','2026-10-19','2026-04-01','2026-10-19','FYTD') t),
   (select to_jsonb(t) from public.fn_tally_classify_export_window('2026-10-19','2026-10-01','2026-10-19','2026-10-01','2026-10-19',null) t),
   costing.fn_apply_batch_true_standard(1)),
'tb_objects', jsonb_build_object('allowed_fn', to_regprocedure('public.fn_costing_view_allowed()') is not null, 'atomic', to_regclass('costing.v_sku_internal_loaded_cost_atomic') is not null,
   'fp_method', to_regclass('costing.v_run_fingerprint_method') is not null, 'origin', to_regclass('costing.v_capacity_value_origin') is not null,
   'fp_cols', (select count(*) from information_schema.columns where table_schema='costing' and table_name='costing_run_fingerprint'))
,
'prov_md5', (select md5(string_agg(t::text,'|' order by t::text)) from costing.v_expense_head_monthly_provision_policy t),
'prov_by_pool', (select jsonb_object_agg(k, v) from (select to_jsonb(t)->>'allocation_pool' k, count(*)||':'||coalesce(sum((to_jsonb(t)->>'normal_monthly_amount')::numeric),0) v from costing.v_expense_head_monthly_provision_policy t group by 1) z),
'ledger_status', (select jsonb_object_agg(k, n) from (select allocation_pool||':'||policy_status||':'||case when effective_to is null then 'cur' else 'closed' end k, count(*) n from costing.cost_head_policy_ledger group by 1) z),
'basis_122_128', (select jsonb_object_agg(refresh_run_id, h) from (select refresh_run_id, md5(string_agg(md5(t::text),'' order by id)) h from costing.sku_sales_allocation_basis_snapshot t where refresh_run_id in (122,128) group by 1) z),
'defs', (select jsonb_build_object('fn_n', count(*), 'fn_md5', md5(string_agg(k||'='||v,'|' order by k))) from (select p.oid::regprocedure::text k, md5(pg_get_functiondef(p.oid)) v from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('costing','public') and p.prokind in ('f','p')) x),
'views', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.oid::regclass::text||'='||md5(pg_get_viewdef(c.oid)),'|' order by c.oid::regclass::text))) from pg_class c where c.relnamespace in ('costing'::regnamespace,'public'::regnamespace) and c.relkind in ('v','m')),
'tables', (select jsonb_build_object('n', count(*), 'md5', md5(string_agg(c.oid::regclass::text,'|' order by c.oid::regclass::text))) from pg_class c where c.relnamespace='costing'::regnamespace and c.relkind in ('r','p')),
'rpc_md5', md5(pg_get_functiondef('costing.rpc_refresh_sku_sales_allocation_basis_snapshot(date,date,bigint)'::regprocedure))
) r